-- ============================================================================
-- CAR RENTAL MANAGEMENT SYSTEM (CRMS)
-- Database: MySQL 8+ / compatible MariaDB versions commonly bundled with XAMPP
-- File: carrental_db.sql
--
-- Import using phpMyAdmin or: mysql -u root -p < carrental_db.sql
-- IMPORTANT: Back up any existing database before importing. This script creates
-- a separate database named carrental_db and does not drop existing databases.
-- Passwords must be generated by PHP password_hash(); do not store plain text.
-- Booking overlap prevention must also be implemented in PHP using transactions
-- and row locks; ordinary UNIQUE constraints cannot prevent overlapping date ranges.
-- ============================================================================

CREATE DATABASE IF NOT EXISTS carrental
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;
USE carrental;

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 1;

-- 1. ACCESS CONTROL ----------------------------------------------------------
CREATE TABLE IF NOT EXISTS roles (
    role_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    role_name VARCHAR(60) NOT NULL,
    description VARCHAR(255) NULL,
    is_system_role TINYINT(1) NOT NULL DEFAULT 1,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (role_id),
    UNIQUE KEY uq_roles_name (role_name)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS permissions (
    permission_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    permission_key VARCHAR(100) NOT NULL,
    description VARCHAR(255) NULL,
    PRIMARY KEY (permission_id),
    UNIQUE KEY uq_permissions_key (permission_key)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS role_permissions (
    role_id BIGINT UNSIGNED NOT NULL,
    permission_id BIGINT UNSIGNED NOT NULL,
    granted_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (role_id, permission_id),
    CONSTRAINT fk_role_permissions_role FOREIGN KEY (role_id) REFERENCES roles(role_id)
      ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT fk_role_permissions_permission FOREIGN KEY (permission_id) REFERENCES permissions(permission_id)
      ON UPDATE CASCADE ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS users (
    user_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    role_id BIGINT UNSIGNED NOT NULL,
    first_name VARCHAR(100) NOT NULL,
    last_name VARCHAR(100) NOT NULL,
    email VARCHAR(190) NULL,
    phone VARCHAR(30) NULL,
    password_hash VARCHAR(255) NOT NULL,
    account_status ENUM('active','inactive','suspended','pending') NOT NULL DEFAULT 'active',
    must_change_password TINYINT(1) NOT NULL DEFAULT 0,
    last_login_at DATETIME NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (user_id),
    UNIQUE KEY uq_users_email (email),
    KEY idx_users_role_status (role_id, account_status),
    CONSTRAINT fk_users_role FOREIGN KEY (role_id) REFERENCES roles(role_id)
      ON UPDATE CASCADE ON DELETE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS password_reset_tokens (
    token_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    user_id BIGINT UNSIGNED NOT NULL,
    token_hash VARCHAR(255) NOT NULL,
    expires_at DATETIME NOT NULL,
    used_at DATETIME NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (token_id),
    KEY idx_password_reset_user_expiry (user_id, expires_at),
    CONSTRAINT fk_password_reset_user FOREIGN KEY (user_id) REFERENCES users(user_id)
      ON UPDATE CASCADE ON DELETE CASCADE
) ENGINE=InnoDB;

-- 2. CUSTOMER AND DRIVER PROFILES -------------------------------------------
CREATE TABLE IF NOT EXISTS customers (
    customer_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    user_id BIGINT UNSIGNED NULL,
    customer_code VARCHAR(30) NOT NULL,
    first_name VARCHAR(100) NOT NULL,
    last_name VARCHAR(100) NOT NULL,
    phone VARCHAR(30) NOT NULL,
    email VARCHAR(190) NULL,
    address_line VARCHAR(255) NULL,
    city VARCHAR(100) NULL,
    country VARCHAR(100) NOT NULL DEFAULT 'Rwanda',
    identification_type ENUM('national_id','passport','other') NULL,
    identification_number VARCHAR(100) NULL,
    driving_license_number VARCHAR(100) NULL,
    license_expiry_date DATE NULL,
    date_of_birth DATE NULL,
    notes TEXT NULL,
    status ENUM('active','inactive','blacklisted') NOT NULL DEFAULT 'active',
    created_by BIGINT UNSIGNED NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (customer_id),
    UNIQUE KEY uq_customers_code (customer_code),
    UNIQUE KEY uq_customers_user (user_id),
    UNIQUE KEY uq_customers_identification (identification_type, identification_number),
    KEY idx_customers_name (last_name, first_name),
    KEY idx_customers_phone (phone),
    KEY idx_customers_email (email),
    CONSTRAINT fk_customers_user FOREIGN KEY (user_id) REFERENCES users(user_id)
      ON UPDATE CASCADE ON DELETE SET NULL,
    CONSTRAINT fk_customers_created_by FOREIGN KEY (created_by) REFERENCES users(user_id)
      ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS drivers (
    driver_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    user_id BIGINT UNSIGNED NULL,
    driver_code VARCHAR(30) NOT NULL,
    first_name VARCHAR(100) NOT NULL,
    last_name VARCHAR(100) NOT NULL,
    phone VARCHAR(30) NOT NULL,
    email VARCHAR(190) NULL,
    license_number VARCHAR(100) NOT NULL,
    license_expiry_date DATE NOT NULL,
    availability_status ENUM('available','assigned','unavailable','inactive') NOT NULL DEFAULT 'available',
    notes TEXT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (driver_id),
    UNIQUE KEY uq_drivers_code (driver_code),
    UNIQUE KEY uq_drivers_user (user_id),
    UNIQUE KEY uq_drivers_license (license_number),
    KEY idx_drivers_availability (availability_status),
    CONSTRAINT fk_drivers_user FOREIGN KEY (user_id) REFERENCES users(user_id)
      ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB;

-- 3. VEHICLE FLEET -----------------------------------------------------------
CREATE TABLE IF NOT EXISTS vehicle_categories (
    category_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    category_name VARCHAR(80) NOT NULL,
    description VARCHAR(255) NULL,
    default_daily_rate DECIMAL(12,2) NOT NULL DEFAULT 0.00,
    default_weekly_rate DECIMAL(12,2) NULL,
    default_monthly_rate DECIMAL(12,2) NULL,
    passenger_capacity TINYINT UNSIGNED NULL,
    luggage_capacity TINYINT UNSIGNED NULL,
    is_active TINYINT(1) NOT NULL DEFAULT 1,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (category_id),
    UNIQUE KEY uq_vehicle_categories_name (category_name),
    CONSTRAINT chk_category_daily_rate CHECK (default_daily_rate >= 0),
    CONSTRAINT chk_category_weekly_rate CHECK (default_weekly_rate IS NULL OR default_weekly_rate >= 0),
    CONSTRAINT chk_category_monthly_rate CHECK (default_monthly_rate IS NULL OR default_monthly_rate >= 0)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS vehicles (
    vehicle_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    category_id BIGINT UNSIGNED NOT NULL,
    registration_no VARCHAR(30) NOT NULL,
    vin VARCHAR(80) NULL,
    make VARCHAR(80) NOT NULL,
    model VARCHAR(80) NOT NULL,
    manufacture_year SMALLINT UNSIGNED NULL,
    colour VARCHAR(40) NULL,
    transmission ENUM('manual','automatic','other') NOT NULL DEFAULT 'manual',
    fuel_type ENUM('petrol','diesel','hybrid','electric','other') NOT NULL DEFAULT 'petrol',
    passenger_capacity TINYINT UNSIGNED NULL,
    luggage_capacity TINYINT UNSIGNED NULL,
    daily_rate DECIMAL(12,2) NOT NULL,
    weekly_rate DECIMAL(12,2) NULL,
    monthly_rate DECIMAL(12,2) NULL,
    current_mileage INT UNSIGNED NOT NULL DEFAULT 0,
    fuel_level_percent DECIMAL(5,2) NULL,
    status ENUM('available','reserved','rented','maintenance','inactive') NOT NULL DEFAULT 'available',
    insurance_policy_no VARCHAR(100) NULL,
    insurance_expiry_date DATE NULL,
    inspection_expiry_date DATE NULL,
    description TEXT NULL,
    created_by BIGINT UNSIGNED NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (vehicle_id),
    UNIQUE KEY uq_vehicles_registration (registration_no),
    UNIQUE KEY uq_vehicles_vin (vin),
    KEY idx_vehicles_search (category_id, status, daily_rate),
    KEY idx_vehicles_make_model (make, model),
    KEY idx_vehicles_status (status),
    CONSTRAINT fk_vehicles_category FOREIGN KEY (category_id) REFERENCES vehicle_categories(category_id)
      ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_vehicles_created_by FOREIGN KEY (created_by) REFERENCES users(user_id)
      ON UPDATE CASCADE ON DELETE SET NULL,
    CONSTRAINT chk_vehicle_daily_rate CHECK (daily_rate >= 0),
    CONSTRAINT chk_vehicle_weekly_rate CHECK (weekly_rate IS NULL OR weekly_rate >= 0),
    CONSTRAINT chk_vehicle_monthly_rate CHECK (monthly_rate IS NULL OR monthly_rate >= 0),
    CONSTRAINT chk_vehicle_fuel_level CHECK (fuel_level_percent IS NULL OR fuel_level_percent BETWEEN 0 AND 100)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS vehicle_images (
    image_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    vehicle_id BIGINT UNSIGNED NOT NULL,
    image_path VARCHAR(500) NOT NULL,
    alt_text VARCHAR(255) NULL,
    is_primary TINYINT(1) NOT NULL DEFAULT 0,
    uploaded_by BIGINT UNSIGNED NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (image_id),
    KEY idx_vehicle_images_vehicle (vehicle_id, is_primary),
    CONSTRAINT fk_vehicle_images_vehicle FOREIGN KEY (vehicle_id) REFERENCES vehicles(vehicle_id)
      ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT fk_vehicle_images_uploader FOREIGN KEY (uploaded_by) REFERENCES users(user_id)
      ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB;

-- 4. RESERVATIONS AND RENTAL AGREEMENTS --------------------------------------
CREATE TABLE IF NOT EXISTS reservations (
    reservation_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    reservation_code VARCHAR(40) NOT NULL,
    customer_id BIGINT UNSIGNED NOT NULL,
    vehicle_id BIGINT UNSIGNED NOT NULL,
    requested_driver_id BIGINT UNSIGNED NULL,
    pickup_datetime DATETIME NOT NULL,
    return_datetime DATETIME NOT NULL,
    pickup_location VARCHAR(255) NULL,
    return_location VARCHAR(255) NULL,
    daily_rate DECIMAL(12,2) NOT NULL,
    estimated_days DECIMAL(8,2) NOT NULL DEFAULT 1.00,
    estimated_amount DECIMAL(12,2) NOT NULL DEFAULT 0.00,
    discount_amount DECIMAL(12,2) NOT NULL DEFAULT 0.00,
    tax_amount DECIMAL(12,2) NOT NULL DEFAULT 0.00,
    security_deposit DECIMAL(12,2) NOT NULL DEFAULT 0.00,
    status ENUM('pending','confirmed','cancelled','rejected','completed','no_show') NOT NULL DEFAULT 'pending',
    customer_notes TEXT NULL,
    internal_notes TEXT NULL,
    cancellation_reason VARCHAR(500) NULL,
    created_by BIGINT UNSIGNED NULL,
    confirmed_by BIGINT UNSIGNED NULL,
    confirmed_at DATETIME NULL,
    cancelled_at DATETIME NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (reservation_id),
    UNIQUE KEY uq_reservations_code (reservation_code),
    KEY idx_reservations_vehicle_period (vehicle_id, status, pickup_datetime, return_datetime),
    KEY idx_reservations_customer (customer_id, created_at),
    KEY idx_reservations_status_pickup (status, pickup_datetime),
    CONSTRAINT fk_reservations_customer FOREIGN KEY (customer_id) REFERENCES customers(customer_id)
      ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_reservations_vehicle FOREIGN KEY (vehicle_id) REFERENCES vehicles(vehicle_id)
      ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_reservations_driver FOREIGN KEY (requested_driver_id) REFERENCES drivers(driver_id)
      ON UPDATE CASCADE ON DELETE SET NULL,
    CONSTRAINT fk_reservations_created_by FOREIGN KEY (created_by) REFERENCES users(user_id)
      ON UPDATE CASCADE ON DELETE SET NULL,
    CONSTRAINT fk_reservations_confirmed_by FOREIGN KEY (confirmed_by) REFERENCES users(user_id)
      ON UPDATE CASCADE ON DELETE SET NULL,
    CONSTRAINT chk_reservation_period CHECK (return_datetime > pickup_datetime),
    CONSTRAINT chk_reservation_rate CHECK (daily_rate >= 0),
    CONSTRAINT chk_reservation_days CHECK (estimated_days > 0),
    CONSTRAINT chk_reservation_amounts CHECK (estimated_amount >= 0 AND discount_amount >= 0 AND tax_amount >= 0 AND security_deposit >= 0)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS rental_agreements (
    agreement_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    agreement_number VARCHAR(40) NOT NULL,
    reservation_id BIGINT UNSIGNED NOT NULL,
    customer_id BIGINT UNSIGNED NOT NULL,
    vehicle_id BIGINT UNSIGNED NOT NULL,
    prepared_by BIGINT UNSIGNED NULL,
    agreed_daily_rate DECIMAL(12,2) NOT NULL,
    security_deposit DECIMAL(12,2) NOT NULL DEFAULT 0.00,
    terms_and_conditions TEXT NULL,
    signed_at DATETIME NULL,
    document_path VARCHAR(500) NULL,
    status ENUM('draft','issued','signed','active','completed','terminated') NOT NULL DEFAULT 'draft',
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (agreement_id),
    UNIQUE KEY uq_agreement_number (agreement_number),
    UNIQUE KEY uq_agreement_reservation (reservation_id),
    KEY idx_agreement_customer (customer_id),
    CONSTRAINT fk_agreements_reservation FOREIGN KEY (reservation_id) REFERENCES reservations(reservation_id)
      ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_agreements_customer FOREIGN KEY (customer_id) REFERENCES customers(customer_id)
      ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_agreements_vehicle FOREIGN KEY (vehicle_id) REFERENCES vehicles(vehicle_id)
      ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_agreements_prepared_by FOREIGN KEY (prepared_by) REFERENCES users(user_id)
      ON UPDATE CASCADE ON DELETE SET NULL,
    CONSTRAINT chk_agreement_amounts CHECK (agreed_daily_rate >= 0 AND security_deposit >= 0)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS rentals (
    rental_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    rental_number VARCHAR(40) NOT NULL,
    reservation_id BIGINT UNSIGNED NOT NULL,
    agreement_id BIGINT UNSIGNED NOT NULL,
    customer_id BIGINT UNSIGNED NOT NULL,
    vehicle_id BIGINT UNSIGNED NOT NULL,
    assigned_driver_id BIGINT UNSIGNED NULL,
    actual_pickup_datetime DATETIME NULL,
    expected_return_datetime DATETIME NOT NULL,
    actual_return_datetime DATETIME NULL,
    pickup_mileage INT UNSIGNED NULL,
    return_mileage INT UNSIGNED NULL,
    pickup_fuel_percent DECIMAL(5,2) NULL,
    return_fuel_percent DECIMAL(5,2) NULL,
    base_amount DECIMAL(12,2) NOT NULL DEFAULT 0.00,
    extra_mileage_fee DECIMAL(12,2) NOT NULL DEFAULT 0.00,
    late_return_fee DECIMAL(12,2) NOT NULL DEFAULT 0.00,
    damage_fee DECIMAL(12,2) NOT NULL DEFAULT 0.00,
    cleaning_fee DECIMAL(12,2) NOT NULL DEFAULT 0.00,
    other_charges DECIMAL(12,2) NOT NULL DEFAULT 0.00,
    discount_amount DECIMAL(12,2) NOT NULL DEFAULT 0.00,
    tax_amount DECIMAL(12,2) NOT NULL DEFAULT 0.00,
    final_amount DECIMAL(12,2) NOT NULL DEFAULT 0.00,
    status ENUM('scheduled','active','overdue','returned','inspected','closed','cancelled') NOT NULL DEFAULT 'scheduled',
    pickup_notes TEXT NULL,
    return_notes TEXT NULL,
    handled_by BIGINT UNSIGNED NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (rental_id),
    UNIQUE KEY uq_rental_number (rental_number),
    UNIQUE KEY uq_rental_reservation (reservation_id),
    UNIQUE KEY uq_rental_agreement (agreement_id),
    KEY idx_rentals_vehicle_status (vehicle_id, status),
    KEY idx_rentals_expected_return (status, expected_return_datetime),
    KEY idx_rentals_customer (customer_id, created_at),
    CONSTRAINT fk_rentals_reservation FOREIGN KEY (reservation_id) REFERENCES reservations(reservation_id)
      ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_rentals_agreement FOREIGN KEY (agreement_id) REFERENCES rental_agreements(agreement_id)
      ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_rentals_customer FOREIGN KEY (customer_id) REFERENCES customers(customer_id)
      ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_rentals_vehicle FOREIGN KEY (vehicle_id) REFERENCES vehicles(vehicle_id)
      ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_rentals_driver FOREIGN KEY (assigned_driver_id) REFERENCES drivers(driver_id)
      ON UPDATE CASCADE ON DELETE SET NULL,
    CONSTRAINT fk_rentals_handler FOREIGN KEY (handled_by) REFERENCES users(user_id)
      ON UPDATE CASCADE ON DELETE SET NULL,
    CONSTRAINT chk_rental_dates CHECK (actual_return_datetime IS NULL OR actual_pickup_datetime IS NULL OR actual_return_datetime >= actual_pickup_datetime),
    CONSTRAINT chk_rental_fuel CHECK ((pickup_fuel_percent IS NULL OR pickup_fuel_percent BETWEEN 0 AND 100) AND (return_fuel_percent IS NULL OR return_fuel_percent BETWEEN 0 AND 100)),
    CONSTRAINT chk_rental_amounts CHECK (base_amount >= 0 AND extra_mileage_fee >= 0 AND late_return_fee >= 0 AND damage_fee >= 0 AND cleaning_fee >= 0 AND other_charges >= 0 AND discount_amount >= 0 AND tax_amount >= 0 AND final_amount >= 0)
) ENGINE=InnoDB;

-- 5. PICKUP/RETURN INSPECTIONS -----------------------------------------------
CREATE TABLE IF NOT EXISTS vehicle_inspections (
    inspection_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    rental_id BIGINT UNSIGNED NOT NULL,
    vehicle_id BIGINT UNSIGNED NOT NULL,
    inspected_by BIGINT UNSIGNED NULL,
    inspection_type ENUM('pickup','return','routine','damage_followup') NOT NULL,
    inspected_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    odometer_reading INT UNSIGNED NULL,
    fuel_level_percent DECIMAL(5,2) NULL,
    exterior_condition ENUM('excellent','good','fair','poor') NULL,
    interior_condition ENUM('excellent','good','fair','poor') NULL,
    cleanliness ENUM('clean','acceptable','needs_cleaning') NULL,
    damage_notes TEXT NULL,
    other_notes TEXT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (inspection_id),
    KEY idx_inspections_rental_type (rental_id, inspection_type),
    KEY idx_inspections_vehicle_date (vehicle_id, inspected_at),
    CONSTRAINT fk_inspections_rental FOREIGN KEY (rental_id) REFERENCES rentals(rental_id)
      ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_inspections_vehicle FOREIGN KEY (vehicle_id) REFERENCES vehicles(vehicle_id)
      ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_inspections_inspector FOREIGN KEY (inspected_by) REFERENCES users(user_id)
      ON UPDATE CASCADE ON DELETE SET NULL,
    CONSTRAINT chk_inspection_fuel CHECK (fuel_level_percent IS NULL OR fuel_level_percent BETWEEN 0 AND 100)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS inspection_images (
    inspection_image_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    inspection_id BIGINT UNSIGNED NOT NULL,
    image_path VARCHAR(500) NOT NULL,
    description VARCHAR(255) NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (inspection_image_id),
    KEY idx_inspection_images_inspection (inspection_id),
    CONSTRAINT fk_inspection_images_inspection FOREIGN KEY (inspection_id) REFERENCES vehicle_inspections(inspection_id)
      ON UPDATE CASCADE ON DELETE CASCADE
) ENGINE=InnoDB;

-- 6. INVOICING, PAYMENTS, DEPOSITS AND REFUNDS -------------------------------
CREATE TABLE IF NOT EXISTS invoices (
    invoice_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    invoice_number VARCHAR(40) NOT NULL,
    customer_id BIGINT UNSIGNED NOT NULL,
    reservation_id BIGINT UNSIGNED NULL,
    rental_id BIGINT UNSIGNED NULL,
    issued_by BIGINT UNSIGNED NULL,
    issue_date DATE NOT NULL,
    due_date DATE NULL,
    subtotal DECIMAL(12,2) NOT NULL DEFAULT 0.00,
    discount_amount DECIMAL(12,2) NOT NULL DEFAULT 0.00,
    tax_amount DECIMAL(12,2) NOT NULL DEFAULT 0.00,
    total_amount DECIMAL(12,2) NOT NULL DEFAULT 0.00,
    currency CHAR(3) NOT NULL DEFAULT 'RWF',
    status ENUM('draft','issued','partially_paid','paid','overdue','void','refunded') NOT NULL DEFAULT 'draft',
    notes TEXT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (invoice_id),
    UNIQUE KEY uq_invoice_number (invoice_number),
    KEY idx_invoices_customer_date (customer_id, issue_date),
    KEY idx_invoices_status_due (status, due_date),
    KEY idx_invoices_reservation (reservation_id),
    KEY idx_invoices_rental (rental_id),
    CONSTRAINT fk_invoices_customer FOREIGN KEY (customer_id) REFERENCES customers(customer_id)
      ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_invoices_reservation FOREIGN KEY (reservation_id) REFERENCES reservations(reservation_id)
      ON UPDATE CASCADE ON DELETE SET NULL,
    CONSTRAINT fk_invoices_rental FOREIGN KEY (rental_id) REFERENCES rentals(rental_id)
      ON UPDATE CASCADE ON DELETE SET NULL,
    CONSTRAINT fk_invoices_issuer FOREIGN KEY (issued_by) REFERENCES users(user_id)
      ON UPDATE CASCADE ON DELETE SET NULL,
    CONSTRAINT chk_invoice_amounts CHECK (subtotal >= 0 AND discount_amount >= 0 AND tax_amount >= 0 AND total_amount >= 0)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS invoice_items (
    invoice_item_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    invoice_id BIGINT UNSIGNED NOT NULL,
    item_type ENUM('rental','driver','extra_mileage','late_return','damage','cleaning','fuel','delivery','discount','tax','other') NOT NULL DEFAULT 'other',
    description VARCHAR(255) NOT NULL,
    quantity DECIMAL(10,2) NOT NULL DEFAULT 1.00,
    unit_price DECIMAL(12,2) NOT NULL DEFAULT 0.00,
    line_total DECIMAL(12,2) NOT NULL DEFAULT 0.00,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (invoice_item_id),
    KEY idx_invoice_items_invoice (invoice_id),
    CONSTRAINT fk_invoice_items_invoice FOREIGN KEY (invoice_id) REFERENCES invoices(invoice_id)
      ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT chk_invoice_item_values CHECK (quantity >= 0 AND unit_price >= 0 AND line_total >= 0)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS payments (
    payment_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    payment_number VARCHAR(40) NOT NULL,
    invoice_id BIGINT UNSIGNED NOT NULL,
    received_by BIGINT UNSIGNED NULL,
    amount DECIMAL(12,2) NOT NULL,
    payment_method ENUM('cash','bank_transfer','card','mobile_money','online','other') NOT NULL,
    transaction_reference VARCHAR(150) NULL,
    payment_date DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    status ENUM('pending','completed','failed','cancelled','partially_refunded','refunded') NOT NULL DEFAULT 'completed',
    provider_name VARCHAR(100) NULL,
    notes VARCHAR(500) NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (payment_id),
    UNIQUE KEY uq_payment_number (payment_number),
    UNIQUE KEY uq_payment_transaction_reference (transaction_reference),
    KEY idx_payments_invoice_date (invoice_id, payment_date),
    KEY idx_payments_status_date (status, payment_date),
    CONSTRAINT fk_payments_invoice FOREIGN KEY (invoice_id) REFERENCES invoices(invoice_id)
      ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_payments_receiver FOREIGN KEY (received_by) REFERENCES users(user_id)
      ON UPDATE CASCADE ON DELETE SET NULL,
    CONSTRAINT chk_payment_amount CHECK (amount > 0)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS payment_refunds (
    refund_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    payment_id BIGINT UNSIGNED NOT NULL,
    refund_number VARCHAR(40) NOT NULL,
    amount DECIMAL(12,2) NOT NULL,
    reason VARCHAR(500) NOT NULL,
    refund_method ENUM('cash','bank_transfer','card','mobile_money','original_method','other') NOT NULL,
    transaction_reference VARCHAR(150) NULL,
    status ENUM('requested','approved','processed','rejected','failed') NOT NULL DEFAULT 'requested',
    requested_by BIGINT UNSIGNED NULL,
    approved_by BIGINT UNSIGNED NULL,
    processed_at DATETIME NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (refund_id),
    UNIQUE KEY uq_refund_number (refund_number),
    UNIQUE KEY uq_refund_transaction_reference (transaction_reference),
    KEY idx_refunds_payment_status (payment_id, status),
    CONSTRAINT fk_refunds_payment FOREIGN KEY (payment_id) REFERENCES payments(payment_id)
      ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_refunds_requester FOREIGN KEY (requested_by) REFERENCES users(user_id)
      ON UPDATE CASCADE ON DELETE SET NULL,
    CONSTRAINT fk_refunds_approver FOREIGN KEY (approved_by) REFERENCES users(user_id)
      ON UPDATE CASCADE ON DELETE SET NULL,
    CONSTRAINT chk_refund_amount CHECK (amount > 0)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS deposit_transactions (
    deposit_transaction_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    reservation_id BIGINT UNSIGNED NULL,
    rental_id BIGINT UNSIGNED NULL,
    customer_id BIGINT UNSIGNED NOT NULL,
    transaction_type ENUM('received','deduction','refund','returned','adjustment') NOT NULL,
    amount DECIMAL(12,2) NOT NULL,
    transaction_date DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    payment_method ENUM('cash','bank_transfer','card','mobile_money','online','other') NULL,
    reference_number VARCHAR(150) NULL,
    reason VARCHAR(500) NULL,
    processed_by BIGINT UNSIGNED NULL,
    status ENUM('pending','completed','cancelled') NOT NULL DEFAULT 'completed',
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (deposit_transaction_id),
    KEY idx_deposits_customer_date (customer_id, transaction_date),
    KEY idx_deposits_reservation (reservation_id),
    KEY idx_deposits_rental (rental_id),
    CONSTRAINT fk_deposits_reservation FOREIGN KEY (reservation_id) REFERENCES reservations(reservation_id)
      ON UPDATE CASCADE ON DELETE SET NULL,
    CONSTRAINT fk_deposits_rental FOREIGN KEY (rental_id) REFERENCES rentals(rental_id)
      ON UPDATE CASCADE ON DELETE SET NULL,
    CONSTRAINT fk_deposits_customer FOREIGN KEY (customer_id) REFERENCES customers(customer_id)
      ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_deposits_processor FOREIGN KEY (processed_by) REFERENCES users(user_id)
      ON UPDATE CASCADE ON DELETE SET NULL,
    CONSTRAINT chk_deposit_amount CHECK (amount > 0)
) ENGINE=InnoDB;

-- 7. MAINTENANCE AND DRIVER ASSIGNMENTS --------------------------------------
CREATE TABLE IF NOT EXISTS maintenance_records (
    maintenance_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    maintenance_number VARCHAR(40) NOT NULL,
    vehicle_id BIGINT UNSIGNED NOT NULL,
    reported_by BIGINT UNSIGNED NULL,
    assigned_to BIGINT UNSIGNED NULL,
    maintenance_type ENUM('routine_service','repair','inspection','tyres','oil_change','bodywork','other') NOT NULL DEFAULT 'other',
    title VARCHAR(180) NOT NULL,
    description TEXT NULL,
    service_provider VARCHAR(180) NULL,
    start_date DATE NOT NULL,
    expected_completion_date DATE NULL,
    completed_date DATE NULL,
    odometer_reading INT UNSIGNED NULL,
    cost DECIMAL(12,2) NOT NULL DEFAULT 0.00,
    next_service_date DATE NULL,
    status ENUM('scheduled','in_progress','completed','cancelled') NOT NULL DEFAULT 'scheduled',
    notes TEXT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (maintenance_id),
    UNIQUE KEY uq_maintenance_number (maintenance_number),
    KEY idx_maintenance_vehicle_status (vehicle_id, status),
    KEY idx_maintenance_dates (start_date, expected_completion_date),
    CONSTRAINT fk_maintenance_vehicle FOREIGN KEY (vehicle_id) REFERENCES vehicles(vehicle_id)
      ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_maintenance_reporter FOREIGN KEY (reported_by) REFERENCES users(user_id)
      ON UPDATE CASCADE ON DELETE SET NULL,
    CONSTRAINT fk_maintenance_assignee FOREIGN KEY (assigned_to) REFERENCES users(user_id)
      ON UPDATE CASCADE ON DELETE SET NULL,
    CONSTRAINT chk_maintenance_cost CHECK (cost >= 0),
    CONSTRAINT chk_maintenance_dates CHECK (expected_completion_date IS NULL OR expected_completion_date >= start_date)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS driver_assignments (
    driver_assignment_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    driver_id BIGINT UNSIGNED NOT NULL,
    rental_id BIGINT UNSIGNED NOT NULL,
    assigned_by BIGINT UNSIGNED NULL,
    assigned_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    unassigned_at DATETIME NULL,
    notes VARCHAR(500) NULL,
    PRIMARY KEY (driver_assignment_id),
    KEY idx_driver_assignments_driver (driver_id, assigned_at),
    KEY idx_driver_assignments_rental (rental_id),
    CONSTRAINT fk_driver_assignments_driver FOREIGN KEY (driver_id) REFERENCES drivers(driver_id)
      ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_driver_assignments_rental FOREIGN KEY (rental_id) REFERENCES rentals(rental_id)
      ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_driver_assignments_assigner FOREIGN KEY (assigned_by) REFERENCES users(user_id)
      ON UPDATE CASCADE ON DELETE SET NULL,
    CONSTRAINT chk_driver_assignment_dates CHECK (unassigned_at IS NULL OR unassigned_at >= assigned_at)
) ENGINE=InnoDB;

-- 8. NOTIFICATIONS AND AUDIT TRAIL ------------------------------------------
CREATE TABLE IF NOT EXISTS notifications (
    notification_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    user_id BIGINT UNSIGNED NULL,
    customer_id BIGINT UNSIGNED NULL,
    channel ENUM('in_app','email','sms') NOT NULL DEFAULT 'in_app',
    notification_type VARCHAR(80) NOT NULL,
    subject VARCHAR(200) NULL,
    message TEXT NOT NULL,
    related_entity_type VARCHAR(60) NULL,
    related_entity_id BIGINT UNSIGNED NULL,
    status ENUM('queued','sent','delivered','failed','read') NOT NULL DEFAULT 'queued',
    scheduled_at DATETIME NULL,
    sent_at DATETIME NULL,
    read_at DATETIME NULL,
    provider_reference VARCHAR(150) NULL,
    error_message VARCHAR(500) NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (notification_id),
    KEY idx_notifications_user_status (user_id, status, created_at),
    KEY idx_notifications_customer_status (customer_id, status, created_at),
    KEY idx_notifications_schedule (status, scheduled_at),
    CONSTRAINT fk_notifications_user FOREIGN KEY (user_id) REFERENCES users(user_id)
      ON UPDATE CASCADE ON DELETE SET NULL,
    CONSTRAINT fk_notifications_customer FOREIGN KEY (customer_id) REFERENCES customers(customer_id)
      ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS audit_logs (
    audit_log_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    user_id BIGINT UNSIGNED NULL,
    action VARCHAR(100) NOT NULL,
    entity_type VARCHAR(100) NOT NULL,
    entity_id VARCHAR(100) NULL,
    description VARCHAR(1000) NULL,
    old_values JSON NULL,
    new_values JSON NULL,
    ip_address VARCHAR(45) NULL,
    user_agent VARCHAR(500) NULL,
    result ENUM('success','failure','denied') NOT NULL DEFAULT 'success',
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (audit_log_id),
    KEY idx_audit_user_date (user_id, created_at),
    KEY idx_audit_entity (entity_type, entity_id),
    KEY idx_audit_action_date (action, created_at),
    CONSTRAINT fk_audit_user FOREIGN KEY (user_id) REFERENCES users(user_id)
      ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB;

-- 9. APPLICATION SETTINGS ----------------------------------------------------
CREATE TABLE IF NOT EXISTS system_settings (
    setting_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    setting_key VARCHAR(100) NOT NULL,
    setting_value TEXT NULL,
    value_type ENUM('string','number','boolean','json') NOT NULL DEFAULT 'string',
    description VARCHAR(255) NULL,
    is_sensitive TINYINT(1) NOT NULL DEFAULT 0,
    updated_by BIGINT UNSIGNED NULL,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (setting_id),
    UNIQUE KEY uq_system_settings_key (setting_key),
    CONSTRAINT fk_settings_updater FOREIGN KEY (updated_by) REFERENCES users(user_id)
      ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB;

