-- 11. REPORTING VIEWS --------------------------------------------------------
CREATE OR REPLACE VIEW vw_invoice_balances AS
SELECT
    i.invoice_id,
    i.invoice_number,
    i.customer_id,
    i.reservation_id,
    i.rental_id,
    i.issue_date,
    i.due_date,
    i.total_amount,
    COALESCE((
      SELECT SUM(p.amount)
      FROM payments p
      WHERE p.invoice_id = i.invoice_id
        AND p.status IN ('completed','partially_refunded','refunded')
    ), 0.00) AS total_paid_gross,
    COALESCE((
      SELECT SUM(pr.amount)
      FROM payment_refunds pr
      JOIN payments p2 ON p2.payment_id = pr.payment_id
      WHERE p2.invoice_id = i.invoice_id
        AND pr.status = 'processed'
    ), 0.00) AS total_refunded,
    GREATEST(
      i.total_amount
      - COALESCE((SELECT SUM(p.amount) FROM payments p WHERE p.invoice_id = i.invoice_id AND p.status IN ('completed','partially_refunded','refunded')), 0.00)
      + COALESCE((SELECT SUM(pr.amount) FROM payment_refunds pr JOIN payments p2 ON p2.payment_id = pr.payment_id WHERE p2.invoice_id = i.invoice_id AND pr.status = 'processed'), 0.00),
      0.00
    ) AS outstanding_balance,
    i.status
FROM invoices i;

CREATE OR REPLACE VIEW vw_vehicle_current_status AS
SELECT
    v.vehicle_id,
    v.registration_no,
    v.make,
    v.model,
    vc.category_name,
    v.daily_rate,
    v.status AS recorded_status,
    CASE
      WHEN v.status IN ('maintenance','inactive') THEN v.status
      WHEN EXISTS (SELECT 1 FROM rentals r WHERE r.vehicle_id = v.vehicle_id AND r.status IN ('active','overdue')) THEN 'rented'
      WHEN EXISTS (SELECT 1 FROM maintenance_records m WHERE m.vehicle_id = v.vehicle_id AND m.status IN ('scheduled','in_progress')) THEN 'maintenance'
      ELSE v.status
    END AS operational_status
FROM vehicles v
JOIN vehicle_categories vc ON vc.category_id = v.category_id;

